from pathlib import Path
p=Path(__file__).resolve().parent/'플레이.html'
h=p.read_text().replace("const STORAGE='grad.puzzle13.v1'","const STORAGE='grad.puzzle13.v1.persisttest'")
script=r'''<script>(async()=>{await document.fonts.ready;const key='p13-phase',results=JSON.parse(sessionStorage.getItem('p13-checks')||'[]');const wait=ms=>new Promise(r=>setTimeout(r,ms));const click=s=>{const e=document.querySelector(s);if(typeof e.click==='function')e.click();else e.dispatchEvent(new MouseEvent('click',{bubbles:true}))};function check(name,ok){results.push({name,ok:Boolean(ok)});if(!ok)throw Error(name)}function place(m,w,x,y){click('[data-model="'+m+'"]');click('[data-cell="'+x+','+y+'"]');click('[data-word="'+w+'"]')}function valid(){place('y_s','집',0,0);place('y_ns','안',0,1);place('y_ne','주민',0,2);place('y_twin','나',1,1);place('b_give','주다',1,2);place('y_w','열쇠',2,2)}
try{const phase=sessionStorage.getItem(key);if(!phase){Puzzle13.reset();click('#sound');click('#npc-outside');valid();sessionStorage.setItem(key,'assembled');location.reload();return}if(phase==='assembled'){check('reload pieces restored',Puzzle13.getState().pieces.length===6);check('reload heard restored',Puzzle13.getState().heard.outside&&!Puzzle13.getState().heard.inside);check('reload chat restored',!document.querySelector('#conversation').hidden);check('reload graph valid',Puzzle13.analyze().ok);click('#speak');await wait(1250);sessionStorage.setItem('p13-checks',JSON.stringify(results));sessionStorage.setItem(key,'complete');location.reload();return}check('reload completed world',Puzzle13.getState().world.complete&&Puzzle13.getState().world.keyOwner==='inside');check('reload completed screen',!document.querySelector('#complete-panel').hidden);click('#again');click('#npc-inside');valid();click('#speak');click('#restart');await wait(1300);check('restart cancels pending completion',!Puzzle13.getState().world.complete&&Puzzle13.getState().pieces.length===0&&Puzzle13.getState().world.keyOwner==='player');}
catch(e){results.push({name:'exception: '+e.message,ok:false})}const pre=document.createElement('pre');pre.id='verification';pre.hidden=true;pre.textContent=JSON.stringify({passed:results.every(x=>x.ok),checks:results});document.body.appendChild(pre)})();</script>'''
Path('/mnt/c/Users/cj307/AppData/Local/Temp/puzzle13-persistence.html').write_text(h.replace('</body>',script+'</body>'))
